package com.andye.warmod.block;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.radar.station.RadarStationManager;import java.util.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.AABB;public final class RadarStationBlockItem extends BlockItem {public RadarStationBlockItem(Properties p){super(ModBlocks.RADAR_STATION,p);}@Override public InteractionResult place(BlockPlaceContext c){if(c.getLevel().isClientSide())return InteractionResult.SUCCESS;if(!(c.getLevel()instanceof ServerLevel level))return InteractionResult.FAIL;Player player=c.getPlayer();BlockPos centre=c.getClickedPos();Direction facing=player==null?Direction.NORTH:player.getDirection().getOpposite();if(!RadarStationManager.canPlace(level))return fail(player,"Radar Station limit reached");for(var part:RadarStationPart.values()){BlockPos p=RadarStationStructure.position(centre,part,facing);if(level.isOutsideBuildHeight(p)||!level.getWorldBorder().isWithinBounds(p)||level.getBlockEntity(p)!=null||!level.getBlockState(p).canBeReplaced()||(player!=null&&!level.mayInteract(player,p))||!level.getEntities(null,new AABB(p)).isEmpty())return fail(player,"Cannot place complete 3x3x3 Radar Station here");}List<BlockPos>placed=new ArrayList<>();try{for(var part:RadarStationPart.values()){BlockPos p=RadarStationStructure.position(centre,part,facing);BlockState s=ModBlocks.RADAR_STATION.defaultBlockState().setValue(RadarStationBlock.PART,part).setValue(RadarStationBlock.FACING,facing);if(!level.setBlock(p,s,Block.UPDATE_ALL))throw new IllegalStateException();placed.add(p);}if(!(level.getBlockEntity(centre)instanceof RadarStationBlockEntity radar))throw new IllegalStateException();radar.initialize(level,facing,player);if(!RadarStationManager.register(level,radar))throw new IllegalStateException();c.getItemInHand().consume(1,player);return InteractionResult.SUCCESS_SERVER;}catch(RuntimeException e){for(BlockPos p:placed)level.setBlock(p,Blocks.AIR.defaultBlockState(),Block.UPDATE_ALL);return fail(player,"Radar Station placement failed atomically");}}private static InteractionResult fail(Player p,String m){if(p!=null)p.sendSystemMessage(Component.literal(m));return InteractionResult.FAIL;}}